using System;using UnityEngine;using UnityEngine.InputSystem;using TMPro;
namespace CrossTheLine {
public sealed class SynagogueDispute:MonoBehaviour {
 public int Stage{get;private set;}public bool IsCinematic=>rally;public bool ExitReached{get;private set;}public Transform Player=>player;public Vector3 ExitPosition=>new Vector3(0,2.4f,0);
 JourneyGame game;Transform player;Material mat;Sprite square;GameObject environment;Transform[] crowd=new Transform[12];Vector3[] home=new Vector3[12];bool busy,rally,shutdown,oldPixel;float clock;UnityEngine.Rendering.Universal.PixelPerfectCamera pixel;
 public void Initialize(JourneyGame g,Transform p,SpriteRenderer body,Material m,Sprite s,int step){JourneyObjectFactory.BeginStage(this,step);game=g;player=p;mat=m;square=s;pixel=g.journeyCamera.GetComponent<UnityEngine.Rendering.Universal.PixelPerfectCamera>();if(pixel){oldPixel=pixel.enabled;pixel.enabled=false;}ConfigureStep(step);}
 Color C(string h){ColorUtility.TryParseHtmlString("#"+h,out var c);return c;}
 Transform Shape(string n,float x,float y,float w,float h,string c,int order=0){var o=JourneyObjectFactory.Create(n);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 1",new Vector3(x,y,0));o.transform.localScale=new Vector3(w,h,1);var r=o.GetOrAddComponent<SpriteRenderer>();r.sprite=square;r.sharedMaterial=mat;r.color=C(c);r.sortingOrder=order;return o.transform;}
 Transform Actor(string name,Sprite sprite,float x,float y){var o=JourneyObjectFactory.Create(name);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 2",new Vector3(x,y,0));var r=JourneyObjectFactory.Create("Sprite").GetOrAddComponent<SpriteRenderer>();r.transform.SetParent(o.transform,false);r.sprite=sprite;r.sharedMaterial=mat;r.sortingOrder=40;float scale=1.55f/sprite.bounds.size.y;r.transform.localScale=Vector3.one*scale;r.transform.localPosition=new Vector3(-sprite.bounds.center.x*scale,-sprite.bounds.min.y*scale,0);return o.transform;}
 void Label(string text,float x,float y){var o=JourneyObjectFactory.Create(text);o.transform.SetParent(environment.transform,false);o.transform.position=JourneyStageLayout.Point(this,o.transform,"Placement 3",new Vector3(x,y,0));var t=o.GetOrAddComponent<TextMeshPro>();t.font=game.koreanFont;t.text=text;t.fontSize=2.7f;t.color=C("584b3b");t.alignment=TextAlignmentOptions.Center;t.GetComponent<RectTransform>().sizeDelta=new Vector2(8,1);t.GetComponent<MeshRenderer>().sortingOrder=75;}
 public void ConfigureStep(int step){JourneyObjectFactory.BeginStage(this,step);Stage=Mathf.Min(step,3);busy=false;rally=false;clock=0;ExitReached=false;if(environment)Destroy(environment);environment=JourneyObjectFactory.Create("SynagogueHall");environment.transform.SetParent(transform,false);Shape("회당 바닥",0,0,30,18,"d6c6a6",-10);Shape("회당 벽",0,3.4f,22,2.4f,"e9dcbf",-8);Shape("열린 출입문",0,2.7f,2.6f,2.5f,"806d57",-5);Shape("가운데 통로",0,-.6f,2.4f,7.4f,"c7ad81",-6);for(int i=0;i<4;i++){float y=1.2f-i*1.35f;Shape("왼쪽 긴 의자",-4.5f,y,5.7f,.28f,"907051",5);Shape("오른쪽 긴 의자",4.5f,y,5.7f,.28f,"907051",5);}if(Stage<3){Shape("설교 단",0,1.25f,4,.45f,"9d7c56",10);Shape("두루마리 읽는 자리",0,1.7f,1.8f,.55f,"795b3d",30);Shape("두루마리",0,2.05f,.95f,.13f,"eee1be",31);Label("안식일 · 회당",0,3.7f);}else Label("출구 ↑",0,3.7f);
 for(int i=0;i<12;i++){float x=i%2==0?-3-(i%3)*1.15f:3+(i%3)*1.15f;float y=.3f-i/4*1.4f;crowd[i]=Actor(i<3?"바리새인 "+i:"회당 사람 "+i,game.supportingCast[i<3?6:i%2==0?5:2],x,y);home[i]=crowd[i].position;}Actor("용서를 구하는 사람",game.supportingCast[6],-1.7f,-2.8f);if(Stage<3)player.position=JourneyStageLayout.Point(this,player,"Placement 4",new Vector3(0,1.8f,0));else player.position=JourneyStageLayout.Point(this,player,"Placement 5",new Vector3(0,-3.3f,0));game.journeyCamera.orthographicSize=5.625f;UpdateCamera();game.BaptismCinema(false);Hud();}
 void Hud(){string[] goals={"회당에서 말씀을 전하고 죄를 용서하기","바리새인들의 항의에 응답하기","군중이 격해지는 모습을 지켜보기","사람들 사이를 지나 회당 밖으로 나가기"};game.SynagogueHud(goals[Stage],Stage==3?"W / ↑ · 가운데 통로를 따라 출구로 걸어가세요":"E · 다음 이야기    WASD / 방향키 · 이동");}
 public void Tick(float dt,bool canMove,bool press){if(rally){clock+=dt;for(int i=0;i<12;i++){var target=new Vector3(i%2==0?-1.8f:1.8f,-2.1f+(i/2)*.65f,0);crowd[i].position=Vector3.Lerp(home[i],target,Mathf.Clamp01(clock/2));crowd[i].GetChild(0).localRotation=Quaternion.Euler(0,0,Mathf.Sin(clock*8+i)*5);}if(clock>=3){rally=false;game.BaptismCinema(false);game.BaptismAdvance();}return;}if(!canMove||busy)return;var k=Keyboard.current;Vector2 v=Vector2.zero;if(k!=null){v.x=(k.dKey.isPressed||k.rightArrowKey.isPressed?1:0)-(k.aKey.isPressed||k.leftArrowKey.isPressed?1:0);v.y=(k.wKey.isPressed||k.upArrowKey.isPressed?1:0)-(k.sKey.isPressed||k.downArrowKey.isPressed?1:0);}var p=player.position+(Vector3)(v.normalized*3.4f*dt);p.x=Mathf.Clamp(p.x,Stage==3?-1.1f:-7,Stage==3?1.1f:7);p.y=Mathf.Clamp(p.y,-3.4f,2.5f);player.position=p;game.MeetingWalk(v.sqrMagnitude>0,v.x);if(Stage==3){for(int i=0;i<12;i++){float side=i%2==0?-1:1;var desired=new Vector3(side*(Mathf.Abs(player.position.y-crowd[i].position.y)<1.4f?3.3f:2.5f),home[i].y,0);crowd[i].position=Vector3.MoveTowards(crowd[i].position,desired,dt*2.5f);}if(player.position.y>=2.3f){ExitReached=true;game.BaptismAdvance();return;}}Hud();if(press)Interact();}
 public void Interact(){if(busy||IsCinematic||Stage==3)return;if(Vector3.Distance(player.position,new Vector3(0,1.8f,0))>2)return;busy=true;game.MeetingTalk(()=>{busy=false;if(Stage==2){clock=0;rally=true;game.BaptismCinema(true);}else game.BaptismAdvance();});}
 public void UpdateCamera(){game.journeyCamera.transform.position=JourneyStageLayout.Point(this,game.journeyCamera.transform,"Placement 6",new Vector3(0,0,-10));}
 public void Shutdown(){if(shutdown)return;shutdown=true;if(pixel)pixel.enabled=oldPixel;}
 void OnDestroy(){Shutdown();}
}
}
